                        >
                          편집
                        </button>
                        <button
                          type="button"
                          disabled={busyActionId === `prod-del-${product.id}`}
                          onClick={() => handleDeleteProduct(product)}
                          className="h-8 rounded border border-red-200 bg-red-50 px-2.5 text-[12px] font-bold text-red-600"
                        >
                          삭제
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          </div>
        )}

        {/* 4. 탭별 본문: DELIVERY */}
        {activeTab === "delivery" && (
          <div className="grid gap-8 lg:grid-cols-12 items-start">
            <section className="rounded-md border border-[#E4E0D8] bg-white p-5 sm:p-6 lg:col-span-5 space-y-4">
              <h2 className="text-[17px] font-bold text-[#0E1A2B]">
                배송·설치 현장 사례 등록 (AI 제목 보조)
              </h2>
              <p className="text-[12.5px] text-[#6B7280]">
                사진에서 확인되는 제품 유형과 설치 상황에 근거해 제목 초안을 생성합니다. 확인 후 수정하여 게시하세요.
              </p>

              <form onSubmit={handleSaveDeliveryCase} className="space-y-4">
                <div>
                  <label className="hb-label">현장 사진 선택 (최대 5장)</label>
                  <input
                    type="file"
                    accept="image/*"
                    multiple
                    disabled={analyzingDelivery}
                    onChange={handleDeliveryFilesChange}
                    className="mt-1 w-full text-[12px]"
                  />
                </div>

                {(delivObserved.length > 0 || delivReviewNotes.length > 0) && (
                  <div className="rounded border border-[#E4E0D8] bg-[#FAF9F7] p-3 text-[12px] space-y-1.5">
                    {delivObserved.length > 0 && (
                      <p>
                        <strong>📷 판독된 요소:</strong>{" "}
                        {delivObserved.join(", ")}
                      </p>
                    )}
                    {delivReviewNotes.map((n, i) => (
                      <p key={i} className="text-amber-800 font-semibold">
                        ⚠️ {n}
                      </p>
                    ))}
                  </div>
                )}

                <div>
                  <label className="hb-label">
                    배송·설치 사례 제목 (수정 가능) *
                  </label>
                  <input
                    type="text"
                    required
                    value={delivTitle}
                    onChange={(e) => setDelivTitle(e.target.value)}
                    placeholder="사진 첨부 시 AI가 초안을 작성합니다"
                    className="hb-input mt-1"
                  />
                </div>

                <button
                  type="submit"
                  disabled={savingDelivery || analyzingDelivery}
                  className="hb-btn-primary h-11 w-full text-[14px]"
                >
                  {savingDelivery ? "등록 중..." : "제목 확인 완료 및 게시하기"}
                </button>
              </form>
            </section>

            <section className="rounded-md border border-[#E4E0D8] bg-white p-5 sm:p-6 lg:col-span-7 space-y-4">
              <h2 className="text-[17px] font-bold text-[#0E1A2B]">
                등록된 배송·설치 사례 ({deliveryCases.length}건)
              </h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {deliveryCases.map((item) => {
                  const imgs = splitImages(item.image_url);
                  return (
                    <div
                      key={item.id}
                      className="flex items-center gap-3 rounded border border-[#E4E0D8] p-3"
                    >
                      <div className="h-14 w-14 shrink-0 overflow-hidden rounded bg-[#EFECE6]">
                        <SafeImg
                          src={imgs[0]}
                          alt={item.title}
                          className="h-full w-full object-cover"
                        />
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-[13.5px] font-bold text-[#0E1A2B]">
                          {item.title}
                        </p>
                        <p className="text-[11.5px] text-[#8A8478]">
                          {new Date(item.created_at).toLocaleDateString("ko-KR")}
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={() =>
                          handleDeleteDeliveryCase(item.id, item.title)
                        }
                        className="rounded border border-red-200 bg-red-50 px-2.5 py-1 text-[11.5px] font-bold text-red-600"
                      >
                        삭제
                      </button>
                    </div>
                  );
                })}
              </div>
            </section>
          </div>
        )}

        {/* 5. 탭별 본문: NOTIFICATIONS */}
        {activeTab === "notifications" && (
          <section className="rounded-md border border-[#E4E0D8] bg-white p-5 sm:p-6 space-y-5">
            <div>
              <h2 className="text-[18px] font-bold text-[#0E1A2B]">
                외부 알림(Telegram / 알림톡) 발송 상태 관리 및 재시도
              </h2>
              <p className="mt-1 text-[13px] text-[#6B7280]">
                환경변수 미설정이나 외부 서버 오류 시 거짓 성공으로 표시하지 않고,{" "}
                <strong>
                  [발송 대기 / 발송 성공 / 설정 미완료 / 외부 서비스 오류 / 재시도 필요]
                </strong>{" "}
                5가지 상태로 정확히 구분합니다.
              </p>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-[13.5px] border-t border-[#E4E0D8]">
                <thead className="bg-[#FAF9F7] text-[#6B7280] border-b border-[#E4E0D8]">
                  <tr>
                    <th className="py-3 px-4">접수일시 / 고객명</th>
                    <th className="py-3 px-4">구분 / 제목</th>
                    <th className="py-3 px-4">Telegram 알림 상태</th>
                    <th className="py-3 px-4">알림톡 연동 상태</th>
                    <th className="py-3 px-4 text-right">수동 발송 / 재시도</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#EEEBE5]">
                  {inquiries
                    .filter((i) => !i.is_notice)
                    .slice(0, 15)
                    .map((inq) => {
                      const tg = notificationLogs[`telegram:${inq.id}`];
                      const alim = notificationLogs[`alimtalk:${inq.id}`];
                      return (
                        <tr key={inq.id}>
                          <td className="py-3 px-4">
                            <strong className="text-[#0E1A2B]">{inq.name}</strong>
                            <span className="block text-[11.5px] text-[#8A8478]">
                              {new Date(inq.created_at).toLocaleDateString("ko-KR")}
                            </span>
                          </td>
                          <td className="py-3 px-4">
                            <span className="text-[11.5px] font-bold text-[#D9531E] block">
                              {inq.inquiry_type}
                            </span>
                            <span className="truncate block max-w-xs">
                              {inq.category}
                            </span>
                          </td>
                          <td className="py-3 px-4">
                            {tg ? (
                              <div>
                                <span
                                  className={`inline-block rounded px-2 py-0.5 text-[11px] font-bold ${
                                    tg.sent
                                      ? "bg-emerald-100 text-emerald-800"
                                      : "bg-amber-100 text-amber-900"
                                  }`}
                                >
                                  {tg.statusLabel}
                                </span>
                                <p className="mt-1 text-[11.5px] text-[#6B7280]">
                                  {tg.message}
                                </p>
                              </div>
                            ) : (
                              <span className="text-[12px] text-[#8A8478]">
                                발송 대기 / 이력 미조회
                              </span>
                            )}
                          </td>
                          <td className="py-3 px-4">
                            {alim ? (
                              <div>
                                <span className="inline-block rounded bg-neutral-200 px-2 py-0.5 text-[11px] font-bold text-neutral-700">
                                  {alim.statusLabel}
                                </span>
                                <p className="mt-1 text-[11.5px] text-[#6B7280]">
                                  {alim.message}
                                </p>
                              </div>
                            ) : (
                              <span className="text-[12px] text-[#8A8478]">
                                설정 미완료 (대행사 미연결)
                              </span>
                            )}
                          </td>
                          <td className="py-3 px-4 text-right space-x-1.5 whitespace-nowrap">
                            <button
                              type="button"
                              disabled={busyActionId === `notify-telegram-${inq.id}`}
                              onClick={() =>
                                handleManualNotificationDispatch("telegram", inq)
                              }
                              className="rounded bg-[#0E1A2B] px-3 py-1.5 text-[12px] font-bold text-white hover:bg-[#1C2D47] disabled:opacity-50"
                            >
                              Telegram 재발송
                            </button>
                            <button
                              type="button"
                              disabled={busyActionId === `notify-alimtalk-${inq.id}`}
                              onClick={() =>
                                handleManualNotificationDispatch("alimtalk", inq)
                              }
                              className="rounded border border-[#DDD9D1] bg-white px-3 py-1.5 text-[12px] font-bold text-[#4B5260] hover:bg-[#FAF9F7] disabled:opacity-50"
                            >
                              알림톡 상태 점검
                            </button>
                          </td>
                        </tr>
                      );
                    })}
                </tbody>
              </table>
            </div>
          </section>
        )}
      </main>
    </div>
  );
}


import { NextRequest, NextResponse } from "next/server";
import {
  NOTIFICATION_STATUS,
  STORE,
  type NotificationDispatchResult,
} from "../../../lib/site";
import {
  checkRateLimit,
  getClientIp,
  verifyAdminRequest,
} from "../../../lib/server-security";

export const runtime = "nodejs";

export async function POST(req: NextRequest) {
  const nowIso = new Date().toISOString();

  try {
    const ip = getClientIp(req);
    const rate = checkRateLimit(`alimtalk_notify:${ip}`, 12, 60 * 1000);
    if (!rate.allowed) {
      return NextResponse.json(
        {
          success: false,
          channel: "alimtalk",
          status: "RETRY_REQUIRED",
          statusLabel: NOTIFICATION_STATUS.RETRY_REQUIRED,
          sent: false,
          retryable: true,
          message: `요청 제한을 초과했습니다. ${rate.retryAfterSec}초 후 다시 시도해 주세요.`,
          timestamp: nowIso,
        },
        { status: 429 }
      );
    }

    const body = await req.json().catch(() => null);
    if (!body || typeof body !== "object") {
      return NextResponse.json(
        {
          success: false,
          channel: "alimtalk",
          status: "EXTERNAL_ERROR",
          statusLabel: NOTIFICATION_STATUS.EXTERNAL_ERROR,
          sent: false,
          retryable: false,
          message: "잘못된 요청 본문입니다.",
          timestamp: nowIso,
        },
        { status: 400 }
      );
    }

    if (body.forceRetry) {
      const adminCheck = await verifyAdminRequest(req);
      if (!adminCheck.ok) {
        return NextResponse.json(
          {
            success: false,
            channel: "alimtalk",
            status: "EXTERNAL_ERROR",
            statusLabel: NOTIFICATION_STATUS.EXTERNAL_ERROR,
            sent: false,
            retryable: false,
            message: adminCheck.error || "관리자 인증이 필요합니다.",
            timestamp: nowIso,
          },
          { status: adminCheck.status }
        );
      }
    }

    const ALIMTALK_API_KEY = process.env.ALIMTALK_API_KEY;
    const ALIMTALK_USER_ID = process.env.ALIMTALK_USER_ID;
    const SENDER_PHONE = STORE.tel.replace(/[^0-9]/g, "");

    if (!ALIMTALK_API_KEY || !ALIMTALK_USER_ID) {
      const notConfigured: NotificationDispatchResult = {
        channel: "alimtalk",
        status: "NOT_CONFIGURED",
        statusLabel: NOTIFICATION_STATUS.NOT_CONFIGURED,
        sent: false,
        retryable: false,
        message:
          "알림톡 서비스 API 키(ALIMTALK_API_KEY, ALIMTALK_USER_ID)가 아직 설정되지 않았습니다.",
        timestamp: nowIso,
      };
      return NextResponse.json(
        {
          success: false,
          skipped: true,
          configured: false,
          senderConfigured: Boolean(SENDER_PHONE),
          reason: "ALIMTALK_NOT_CONFIGURED",
          ...notConfigured,
        },
        { status: 501 }
      );
    }

    const providerNotLinked: NotificationDispatchResult = {
      channel: "alimtalk",
      status: "NOT_CONFIGURED",
      statusLabel: NOTIFICATION_STATUS.NOT_CONFIGURED,
      sent: false,
      retryable: false,
      message: "알림톡 발송 대행사 연동이 아직 완료되지 않았습니다.",
      timestamp: nowIso,
    };

    return NextResponse.json(
      {
        success: false,
        skipped: true,
        configured: false,
        reason: "ALIMTALK_PROVIDER_NOT_IMPLEMENTED",
        ...providerNotLinked,
      },
      { status: 501 }
    );
  } catch {
    return NextResponse.json(
      {
        success: false,
        channel: "alimtalk",
        status: "RETRY_REQUIRED",
        statusLabel: NOTIFICATION_STATUS.RETRY_REQUIRED,
        sent: false,
        retryable: true,
        message: "알림톡 요청 처리 중 서버 오류가 발생했습니다.",
        timestamp: nowIso,
      },
      { status: 500 }
    );
  }
}


// 파일 경로: app/api/analyze-delivery/route.ts
import { NextRequest, NextResponse } from "next/server";
import { GoogleGenAI } from "@google/genai";
import {
  checkRateLimit,
  getClientIp,
  validateServerImageFiles,
  verifyAdminRequest,
} from "../../../lib/server-security";

export const runtime = "nodejs";

const MAX_FILES = 2;
const MAX_FILE_SIZE = 8 * 1024 * 1024; // 8MB
const DEFAULT_GEMINI_MODEL = process.env.GEMINI_MODEL || "gemini-3.8-flash";
const FALLBACK_GEMINI_MODEL = "gemini-2.5-flash";

export async function POST(req: NextRequest) {
  try {
    const adminCheck = await verifyAdminRequest(req);
    if (!adminCheck.ok) {
      return NextResponse.json(
        { error: adminCheck.error || "관리자 권한이 필요합니다." },
        { status: adminCheck.status }
      );
    }

    const ip = getClientIp(req);
    const rate = checkRateLimit(
      `analyze_delivery:${adminCheck.email || ip}`,
      10,
      60 * 1000
    );
    if (!rate.allowed) {
      return NextResponse.json(
        {
          error: `요청이 너무 많습니다. ${rate.retryAfterSec}초 후 다시 시도해 주세요.`,
        },
        { status: 429 }
      );
    }

    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      return NextResponse.json(
        {
          success: false,
          skipped: true,
          error:
            "서버에 GEMINI_API_KEY가 설정되어 있지 않아 분석을 수행할 수 없습니다.",
        },
        { status: 503 }
      );
    }

    const formData = await req.formData();
    const multipleFiles = formData.getAll("files");
    const entries = multipleFiles.length
      ? multipleFiles
      : formData.getAll("file");
    const files = entries.filter((item): item is File => item instanceof File);

    const fileValidation = await validateServerImageFiles(files, {
      maxFiles: MAX_FILES,
      maxFileSizeBytes: MAX_FILE_SIZE,
    });

    if (!fileValidation.ok || !fileValidation.validated) {
      return NextResponse.json(
        {
          error:
            fileValidation.error || "배송/설치 사진을 올바르게 첨부해 주세요.",
        },
        { status: 400 }
      );
    }

    const prompt = `
당신은 대전 중고가전/업소용 주방기기 전문 매장 '한밭중고전자'의 배송·설치 사례 등록 보조자입니다.
첨부된 현장 사진에서 실제로 확인할 수 있는 '제품 유형'과 '설치/운반 상황'에만 근거하여 [배송·설치 사례 제목 초안]을 1문장(18~38자 내외)으로 작성하세요.

[절대 준수 지침 - 임의 창작 금지]
1. 사진만으로 알 수 없는 정확한 지역명(예: 대전 둔산동, 세종시 등), 고객 실명/상호명, 정확한 제품 모델명, 최종 설치 완료 여부를 임의로 단정하거나 지어내지 마세요.
2. 사진이 운반 중이면 '운반/반입 현장', 자리 배치 상태면 '배송 및 현장 배치'처럼 사진에서 보이는 사실 수준으로만 서술하세요.
3. 사진에서 직접 확인한 요소("observedElements")와 관리자가 게시 전에 확인·보충하면 좋은 항목("needsReview")을 함께 반환하세요.

반드시 다른 부연설명 없이 아래 JSON 규격으로만 응답하세요:
{
  "title": "업소용 45박스 수직 냉장고 주방 현장 반입 및 배치",
  "observedElements": ["업소용 4도어 수직 냉장고", "상업용 주방 타일 바닥 배치 상태"],
  "needsReview": ["배송 지역명이나 구체적인 업종을 표기하려면 제목을 수정해 주세요."]
}
`;

    const imageParts = fileValidation.validated.map((item) => ({
      inlineData: {
        mimeType: item.mimeType,
        data: item.base64,
      },
    }));

    const ai = new GoogleGenAI({ apiKey });
    let modelUsed = DEFAULT_GEMINI_MODEL;
    let response;

    try {
      response = await ai.models.generateContent({
        model: DEFAULT_GEMINI_MODEL,
        contents: [
          {
            role: "user",
            parts: [{ text: prompt }, ...imageParts],
          },
        ],
        config: { responseMimeType: "application/json" },
      });
    } catch (modelErr: unknown) {
      const msg =
        modelErr instanceof Error
          ? modelErr.message
          : String(modelErr || "");
      if (
        DEFAULT_GEMINI_MODEL !== FALLBACK_GEMINI_MODEL &&
        (msg.includes("404") ||
          msg.toLowerCase().includes("not found") ||
          msg.toLowerCase().includes("not supported"))
      ) {
        modelUsed = FALLBACK_GEMINI_MODEL;
        response = await ai.models.generateContent({
          model: FALLBACK_GEMINI_MODEL,
          contents: [
            {
              role: "user",
              parts: [{ text: prompt }, ...imageParts],
            },
          ],
          config: { responseMimeType: "application/json" },
        });
      } else {
        throw modelErr;
      }
    }

    const responseText = response.text?.trim() || "";
    const jsonMatch = responseText.match(/\{[\s\S]*\}/);
    let parsedTitle = "중고가전 현장 배송 및 배치 사례";
    let observedElements: string[] = [];
    let needsReview: string[] = [
      "AI가 작성한 제목 초안입니다. 실제 배송 지역이나 제품명을 확인 후 게시해 주세요.",
    ];

    if (jsonMatch) {
      try {
        const raw = JSON.parse(jsonMatch[0]);
        if (raw.title && typeof raw.title === "string") {
          parsedTitle = raw.title.trim();
        }
        if (Array.isArray(raw.observedElements)) {
          observedElements = raw.observedElements
            .map((x: unknown) => String(x).trim())
            .filter(Boolean);
        }
        if (Array.isArray(raw.needsReview) && raw.needsReview.length > 0) {
          needsReview = raw.needsReview
            .map((x: unknown) => String(x).trim())
            .filter(Boolean);
        }
      } catch {
        console.warn("배송 사진 제목 JSON 파싱 보정");
      }
    }

    return NextResponse.json({
      isDraft: true,
      modelUsed,
      title: parsedTitle,
      observedElements,
      needsReview,
    });
  } catch (error: unknown) {
    console.error(
      "배송 사진 분석 에러:",
      error instanceof Error ? error.message : "Unknown error"
    );
    return NextResponse.json(
      {
        error: "배송 사진 분석에 실패했습니다. 직접 제목을 입력해 주세요.",
      },
      { status: 500 }
    );
  }
}


// 파일 경로: app/api/analyze-inquiry/route.ts
import { NextRequest, NextResponse } from "next/server";
import { GoogleGenAI } from "@google/genai";
import {
  PRODUCT_CATEGORIES,
  normalizeProductCategory,
  type InquiryTypeValue,
  type ProductCategoryValue,
  type AnalyzeInquiryResponse,
  type ExtractedFactItem,
  type PhotoBreakdownItem,
  type BulkRequestedItem,
} from "../../../lib/site";
import {
  checkRateLimit,
  getClientIp,
  validateServerImageFiles,
} from "../../../lib/server-security";

export const runtime = "nodejs";

const MAX_FILES = 3;
const MAX_FILE_SIZE = 8 * 1024 * 1024; // 8MB
const DEFAULT_GEMINI_MODEL = process.env.GEMINI_MODEL || "gemini-3.8-flash";
const FALLBACK_GEMINI_MODEL = "gemini-2.5-flash";

const ALLOWED_INQUIRY_TYPES: readonly InquiryTypeValue[] = [
  "구매 문의",
  "내 물건 팔기",
  "대량·업소용 상담",
  "기타 문의",
];

function normalizeInquiryType(raw: string): InquiryTypeValue {
  const trimmed = raw.trim();
  if ((ALLOWED_INQUIRY_TYPES as readonly string[]).includes(trimmed)) {
    return trimmed as InquiryTypeValue;
  }
  if (trimmed.includes("구매")) return "구매 문의";
  if (trimmed.includes("대량") || trimmed.includes("업소")) {
    return "대량·업소용 상담";
  }
  if (trimmed.includes("기타")) return "기타 문의";
  return "내 물건 팔기";
}

interface UserInputContext {
  inquiryType: InquiryTypeValue;
  photoCount: number;
  userTitle: string;
  userModel: string;
  userRegion: string;
  userDescription: string;
  userBusinessType: string;
  userElectrical: string;
  userVoltageUpgrade: string;
}

const COMMON_AI_PRINCIPLES = `
[공통 핵심 원칙 — 사실과 미확인 정보의 엄격한 분리]
- 당신은 한밭중고전자의 고객 문의 작성을 돕는 보조 도구이며, 확인되지 않은 사실을 결정하는 도구가 아닙니다.
- 사진에서 실제로 확인되는 정보와 사진만으로 확인할 수 없는 정보를 엄격히 구분하세요.
- 모델명, 제조년월, 전압, 소비전력, 제품 수량, 제품 상태 등을 근거 없이 생성하거나 추측하지 마세요.
- 사진에서 판독할 수 없는 값은 빈 문자열("") 또는 "미확인", "고객 확인 필요"로 반환하세요.
- 사진 속 글자가 흐리거나 일부만 보이면 확정하지 말고 "일부 판독(재확인 필요)" 상태로 기록하세요.
- 고객이 현재 폼에 직접 입력한 내용과 사진에서 추출한 내용을 구분하세요. 고객이 입력한 제품명이나 수량을 임의로 바꾸지 마세요.
- 여러 사진이 첨부되면 각 사진(1번, 2번, 3번)의 내용을 개별 분석("photoBreakdown")한 뒤 동일 제품/현장인지 종합하고, 서로 다른 제품이나 현장의 사진을 하나의 제품으로 혼동하지 마세요.
- 확인되지 않은 정보는 상세 문의 초안("descriptionDraft")에 사실처럼 단정해 쓰지 말고, 고객이 채워 넣을 빈칸이나 후속 질문("followUpQuestions")으로 제시하세요.

[절대 혼동 금지 3대 기준]
1. 사진에 보이는 제품 대수 ≠ 고객이 실제로 구매하거나 처분하려는 희망 수량 (고객이 수량을 명시하지 않았다면 희망 수량은 반드시 "미확인"으로 처리)
2. 분전반·콘센트 사진에서 보이는 전기 표시 정보 ≠ 실제 승압 공사 필요 여부 판단 (사진만으로 승압이 필요하다고 절대 단정하지 말고 "모름·현장 확인 필요"로 처리)
3. 외관 사진에서 관찰되는 상태(흠집·외형) ≠ 제품의 실제 작동 상태(냉방·냉동 성능, 압축기, 소음, 누수, 전기 안전성 등 작동 여부는 사진으로 알 수 없으므로 "작동 상태 미확인 — 고객 확인 필요"로 분리)
`;

function buildUserContextBlock(ctx: UserInputContext): string {
  const lines = [
    `• 선택된 상담 유형: ${ctx.inquiryType}`,
    `• 첨부된 사진 수: ${ctx.photoCount}장`,
    ctx.userTitle ? `• 고객 입력 제목/품목: ${ctx.userTitle}` : null,
    ctx.userModel ? `• 고객 입력 모델명: ${ctx.userModel}` : null,
    ctx.userRegion ? `• 고객 입력 지역: ${ctx.userRegion}` : null,
    ctx.userBusinessType ? `• 고객 입력 업종: ${ctx.userBusinessType}` : null,
    ctx.userElectrical ? `• 고객 선택 전기환경: ${ctx.userElectrical}` : null,
    ctx.userVoltageUpgrade
      ? `• 고객 선택 승압여부: ${ctx.userVoltageUpgrade}`
      : null,
    ctx.userDescription
      ? `• 고객 작성 상세내용: ${ctx.userDescription}`
      : null,
  ].filter(Boolean);
  return `[현재 고객이 폼에 직접 입력한 정보]\n${lines.join("\n")}`;
}

function buildBuyPrompt(ctx: UserInputContext): string {
  return `
당신은 대전 중고가전·업소용 주방기기 전문 매장 '한밭중고전자'의 [구매 문의] 전용 AI 분석 도우미입니다.
목적: 고객이 원하는 제품의 재고·가격·배송·설치 상담을 빠르고 정확하게 받을 수 있도록 돕습니다.

${COMMON_AI_PRINCIPLES}

${buildUserContextBlock(ctx)}

