                      <h3 className="text-[21px] sm:text-[23px] font-extrabold tracking-tight mt-0.5">
                        {STORE.name}
                      </h3>
                    </div>
                    <span className="rounded-md bg-[#F7F6F3] border border-[#E6E3DC] px-2.5 py-1 text-[12px] font-bold text-[#0E1A2B]">
