                          ({STORE.mobile})
                        </a>
                      </div>
                    </li>
                    <li className="pb-3.5 border-b border-[#E6E3DC]">
                      <p className="text-[12px] text-[#667085] font-bold mb-1">
                        매장 주소
                      </p>
                      <p className="leading-snug font-bold text-[#0E1A2B]">
                        {STORE.roadAddress}
                      </p>
                      <p className="text-[13px] text-[#434B59] mt-1">
