            <div>
              <label htmlFor="uf-schedule" className="hb-label">
                희망 일정 · 층수(엘리베이터)
              </label>
              <input
                id="uf-schedule"
                type="text"
                value={schedule}
                onChange={(e) => setSchedule(e.target.value)}
                placeholder="예: 금요일 오후 / 1층 상가"
                className="hb-input mt-1.5 h-[52px] sm:h-[56px] text-[16px]"
              />
            </div>
          </div>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5 sm:gap-4">
          <div
            className={
              isNotice || isOther ? "sm:col-span-3" : "sm:col-span-2"
            }
          >
            <label htmlFor="uf-title" className="hb-label">
              {isNotice
                ? "공지 제목 *"
                : isSell
                ? "매입 신청 품목 / 제목 *"
                : isBulk
                ? "업소용·창업 상담 제목 *"
                : "문의 품목 / 제목 *"}
            </label>
            <input
              id="uf-title"
              type="text"
              value={title}
              onChange={(e) => {
                setTitle(e.target.value);
                if (fieldErrors.title)
                  setFieldErrors((p) => ({ ...p, title: "" }));
              }}
              placeholder={
                isSell
                  ? "예: 삼성 양문형 냉장고 방문 매입 견적 문의"
                  : isBulk
                  ? "예: 식당 오픈용 45박스 냉장고·제빙기·세척기 견적 문의"
                  : isOther
                  ? "문의하실 제목을 입력해 주세요"
                  : "예: 캐리어 벽걸이 냉난방기 9평형 재고·설치 문의"
              }
              className={`hb-input mt-1.5 h-[52px] sm:h-[56px] text-[16px] font-semibold ${
                fieldErrors.title ? "border-red-500 ring-1 ring-red-500" : ""
              }`}
            />
          </div>

          {!isNotice && !isOther && (
            <div>
              <label htmlFor="uf-model" className="hb-label">
                모델명{" "}
                <span className="font-normal text-[#667085]">(선택)</span>
              </label>
              <input
                id="uf-model"
                type="text"
                value={model}
                onChange={(e) => setModel(e.target.value)}
                placeholder="스티커 모델명 확인 시 입력"
                className="hb-input mt-1.5 h-[52px] sm:h-[56px] font-mono text-[15.5px]"
              />
            </div>
          )}
        </div>

        <div>
          <label htmlFor="uf-desc" className="hb-label">
            {isNotice ? "공지 본문 내용 *" : "상세 문의 내용 *"}
          </label>
          <textarea
            id="uf-desc"
            rows={bundleApplied || isBulk ? 5 : 4}
            value={description}
            onChange={(e) => {
              setDescription(e.target.value);
              if (fieldErrors.description)
                setFieldErrors((p) => ({ ...p, description: "" }));
            }}
            placeholder={
              isSell
                ? "예: 정상 작동하며 1층 매장이라 반출 용이합니다. 이번 주 금요일 수거 희망합니다."
                : isBulk
                ? "예: 대전 서구 둔산동 1층 식당 오픈 준비 중입니다. 중고 업소용 냉장고와 제빙기 세트 견적 부탁드립니다."
                : "예: 대전 서구 둔산동 1층 상가입니다. 배송 및 기본 설치 포함 견적이 궁금합니다."
            }
            className={`hb-input mt-1.5 py-3.5 text-[16px] resize-y leading-relaxed ${
              fieldErrors.description
                ? "border-red-500 ring-1 ring-red-500"
                : ""
            }`}
          />
        </div>
      </div>

      {/* 6. 하단 개인정보 동의 및 대형 제출 버튼 (높이 56px~60px, 글자 17px~18px) */}
      <div className="pt-4 border-t border-[#E4E0D8] space-y-4">
        {!isNotice && (
          <label className="flex cursor-pointer items-center gap-2.5 text-[14.5px] sm:text-[15px] text-[#434B59]">
            <input
              type="checkbox"
              checked={agreed}
              onChange={(e) => {
                setAgreed(e.target.checked);
                if (fieldErrors.agreed)
                  setFieldErrors((p) => ({ ...p, agreed: "" }));
              }}
              className="h-5 w-5 shrink-0 accent-[#0E1A2B]"
            />
            <span>
              상담·견적 안내를 위한{" "}
              <Link
                href="/privacy"
                target="_blank"
                className="font-extrabold text-[#0E1A2B] underline underline-offset-2"
              >
                개인정보 수집·이용
              </Link>
              에 동의합니다. <span className="text-[#D9531E]">*</span>
            </span>
          </label>
        )}

        <div className="grid grid-cols-1 sm:grid-cols-12 gap-3">
          {!isNotice && (
            <a
              href={smsHref(STORE.mobile, smsBodyDraft)}
              onClick={() =>
                trackEvent("click_sms_consult", {
                  location: "inquiry_form_bottom",
                  inquiry_type: inquiryType,
                })
              }
              className="hb-btn-outline h-14 sm:h-[60px] px-5 text-[17px] sm:text-[18px] font-extrabold sm:col-span-5 whitespace-nowrap"
            >
              <Icon d={ICON.chat} className="h-5 w-5 text-[#D9531E]" />
              <span>문자로 사진 보내기</span>
            </a>
          )}
          {onCancel && (
            <button
              type="button"
              onClick={onCancel}
              disabled={isBusy}
              className="hb-btn-outline h-14 sm:h-[60px] px-6 text-[17px] font-extrabold sm:col-span-3"
            >
              취소
            </button>
          )}
          <button
            type="submit"
            disabled={isBusy}
            className={`${
              isSell || isNotice ? "hb-btn-accent" : "hb-btn-primary"
            } h-14 sm:h-[60px] px-7 text-[17px] sm:text-[18px] font-extrabold shadow-card whitespace-nowrap cursor-pointer ${
              isNotice
                ? onCancel
                  ? "sm:col-span-9"
                  : "sm:col-span-12"
                : onCancel
                ? "sm:col-span-4"
                : "sm:col-span-7"
            }`}
          >
            {phase === "validating"
              ? "입력 확인 중..."
              : phase === "submitting"
              ? "접수 중..."
              : phase === "retrying"
              ? "재시도 중..."
              : isNotice
              ? "공지사항 등록하기"
              : isSell
              ? "무료 매입 견적 신청하기"
              : isBulk
              ? "업소용·창업 상담 신청하기"
              : bundleApplied
              ? "묶음 견적 신청하기"
              : "구매 상담 신청하기"}
          </button>
        </div>
      </div>

      {phase === "error" && submitErrorMsg && (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-[14px] text-red-800 flex flex-wrap items-center justify-between gap-2"
        >
          <span className="font-bold">{submitErrorMsg}</span>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() => executeSubmit(true)}
              className="rounded-lg bg-red-600 px-3.5 py-2 text-[13px] font-bold text-white hover:bg-red-700"
            >
              그대로 재시도
            </button>
            <a
              href={smsHref(STORE.mobile, smsBodyDraft)}
              className="rounded-lg border border-red-300 bg-white px-3.5 py-2 text-[13px] font-bold text-red-700"
            >
              문자({STORE.mobile}) 문의
            </a>
          </div>
        </div>
      )}
    </form>
  );
}


// 파일 경로: components/products/product-card.tsx
"use client";

import React, { useState, useEffect } from "react";
import Link from "next/link";
import toast from "react-hot-toast";
import {
  extractModelName,
  extractSpecCapsules,
  formatProductPrice,
  getQuoteBasket,
  hasProductPrice,
  isProductSold,
  normalizeProductCategory,
  QUOTE_BASKET_EVENT,
  splitImages,
  toggleQuoteBasketItem,
} from "../../lib/site";
import { Icon, ICON, SafeImg } from "../../lib/ui";
import { ProductStatusBadge } from "./product-status-badge";

export interface ProductItem {
  id: string;
  title: string;
  category: string | null;
  description?: string | null;
  image_url: string | null;
  price: number | null;
  status: string | null;
  condition_grade?: string | null;
  created_at: string;
  views?: number | null;
}

export function ProductTrustMicroStrip({
  category,
  className = "",
}: {
  category?: string | null;
  className?: string;
}) {
  const normalizedCategory = normalizeProductCategory(category);
  const isHvac = normalizedCategory === "에어컨/냉난방기";

  const items = [
    {
      title: "세척·작동 점검",
      desc: "입고 후 작동 테스트 및 고압 세척 완료",
      highlight: null,
    },
    {
      title: "무상 A/S 보증",
      desc: "에어컨·냉난방기 8개월 / 그 외 가전 4개월",
      highlight: isHvac
        ? "해당 품목 8개월 보증 (계약조건 기준)"
        : "해당 품목 4개월 보증 (계약조건 기준)",
    },
    {
      title: "세금계산서 발행",
      desc: "사업자 고객을 위한 합법 부가세 증빙 지원",
      highlight: null,
    },
  ] as const;

  return (
    <section
      aria-label="한밭중고전자 핵심 거래 보증 안내"
      className={`rounded-lg border border-[#E6E3DC] bg-[#FAF9F7] ${className}`}
    >
      <div className="grid grid-cols-1 xs:grid-cols-3 divide-y xs:divide-y-0 xs:divide-x divide-[#E6E3DC]">
        {items.map((item) => (
          <div
            key={item.title}
            className="flex flex-col justify-between px-3.5 py-3"
          >
            <div>
              <div className="flex items-center gap-1.5 text-[12.5px] sm:text-[13px] font-bold tracking-[-0.01em] text-[#0E1A2B]">
                <span
                  aria-hidden="true"
                  className="inline-flex h-4 w-4 shrink-0 items-center justify-center rounded-full bg-[#D9531E]/12 text-[10px] font-extrabold text-[#D9531E]"
                >
                  ✓
                </span>
                <span className="truncate">{item.title}</span>
              </div>
              <p className="mt-1 text-[12px] leading-[1.45] text-[#434B59] break-keep">
                {item.desc}
              </p>
            </div>
            {item.highlight && (
              <span className="mt-1.5 inline-block text-[11px] font-semibold text-[#D9531E] break-keep">
                · {item.highlight}
              </span>
            )}
          </div>
        ))}
      </div>
    </section>
  );
}

export function ProductCard({
  product,
  onSelect,
  isSelectMode = false,
  isSelected = false,
  isAdmin = false,
  onDelete,
}: {
  product: ProductItem;
  onSelect?: (product: ProductItem) => void;
  isSelectMode?: boolean;
  isSelected?: boolean;
  isAdmin?: boolean;
  onDelete?: (id: string) => void;
}) {
  const images = splitImages(product.image_url);
  const sold = isProductSold(product.status);
  const categoryLabel = normalizeProductCategory(product.category);
  const priced = hasProductPrice(product.price);
  const priceText = formatProductPrice(product.price, categoryLabel);
  const modelName = extractModelName(product.description, product.title);
  const specCapsules = extractSpecCapsules(
    product.title,
    product.description,
    2
  );

  const [inBasket, setInBasket] = useState(false);

  useEffect(() => {
    const sync = () => {
      setInBasket(getQuoteBasket().some((x) => x.id === product.id));
    };
    sync();
    window.addEventListener(QUOTE_BASKET_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(QUOTE_BASKET_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [product.id]);

  const handleToggleBasket = (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    const res = toggleQuoteBasketItem({
      id: product.id,
      title: product.title,
      category: categoryLabel,
      price: product.price,
      modelName,
      imageUrl: images[0] || null,
    });
    if (res.limitReached) {
      toast.error("견적함에는 최대 8개까지 담을 수 있습니다.");
    } else if (res.added) {
      toast.success("관심 매물 견적함에 담았습니다.");
    } else {
      toast("견적함에서 제외했습니다.");
    }
  };

  const cardInner = (
    <article
      className={`group relative flex h-full flex-col overflow-hidden rounded-xl border bg-white transition-colors duration-150 ${
        isSelected
          ? "border-[#D9531E] ring-2 ring-[#D9531E]"
          : "border-[#E5E2DC] hover:border-[#0E1A2B]"
      }`}
    >
      {/* 1. 상품 사진 영역 */}
      <div className="relative aspect-[4/3] w-full overflow-hidden bg-[#F4F2ED] border-b border-[#E5E2DC]">
        <SafeImg
          src={images[0]}
          alt={product.title}
          className={`h-full w-full object-cover object-center ${
            sold ? "grayscale opacity-70" : ""
          }`}
        />

        {sold && (
          <div className="absolute inset-0 flex items-center justify-center bg-[#0E1A2B]/45">
            <span className="rounded bg-[#0E1A2B]/90 px-4 py-1.5 text-[12.5px] font-bold tracking-wider text-white">
              판매완료
            </span>
          </div>
        )}

        {!sold && images.length > 1 && (
          <span className="pointer-events-none absolute bottom-2.5 right-2.5 z-10 rounded bg-[#0E1A2B]/75 px-2 py-0.5 text-[11px] font-semibold text-white tabular-nums">
            사진 {images.length}장
          </span>
        )}

        {isSelectMode ? (
          <div
            className={`absolute left-3 top-3 z-20 flex h-6 w-6 items-center justify-center rounded border transition-colors ${
              isSelected
                ? "border-[#D9531E] bg-[#D9531E] text-white"
                : "border-[#858076] bg-white/95 text-transparent"
            }`}
          >
            <Icon d={ICON.check} className="h-3.5 w-3.5" />
          </div>
        ) : (
          <div className="absolute left-2.5 top-2.5 sm:left-3 sm:top-3 z-10">
            <ProductStatusBadge
              status={product.status}
              createdAt={product.created_at}
              showNew={false}
            />
          </div>
        )}

        {isAdmin && !isSelectMode && onDelete ? (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              e.preventDefault();
              onDelete(product.id);
            }}
            title="상품 삭제"
            aria-label={`${product.title} 삭제`}
            className="absolute right-2.5 top-2.5 z-20 flex h-7 w-7 items-center justify-center rounded border border-red-200 bg-white/95 text-red-600 shadow hover:bg-red-50 transition-colors"
          >
            <Icon d={ICON.close} className="h-4 w-4" />
          </button>
        ) : (
          !isSelectMode &&
          !sold && (
            <button
              type="button"
              onClick={handleToggleBasket}
              aria-pressed={inBasket}
              title={inBasket ? "견적함에서 제외" : "관심 매물 견적함에 담기"}
              aria-label={`${product.title} ${inBasket ? "견적함에서 제외" : "견적함에 담기"}`}
              className={`absolute right-2.5 top-2.5 z-20 inline-flex items-center gap-1 rounded border px-2 py-1 text-[11px] font-bold transition-colors ${
                inBasket
                  ? "border-[#D9531E] bg-[#D9531E] text-white"
                  : "border-[#CFCAC0] bg-white/95 text-[#0E1A2B] hover:border-[#0E1A2B]"
              }`}
            >
              <Icon d={inBasket ? ICON.check : ICON.plus} className="h-3 w-3" />
              <span>{inBasket ? "담김" : "견적함"}</span>
            </button>
          )
        )}
      </div>

      {/* 2. 상품 정보 영역 — 카테고리 · 제목 · 규격 · 가격의 명확한 타이포 위계 */}
      <div className="flex flex-1 flex-col p-3.5 sm:p-4">
        <div className="flex items-center justify-between gap-2 text-[12px] font-semibold text-[#667085]">
          <span className="truncate">{categoryLabel}</span>
          {typeof product.views === "number" && product.views > 0 ? (
            <span className="shrink-0 text-[11.5px] text-[#858076] tabular-nums">
              조회 {product.views}
            </span>
          ) : null}
        </div>

        <h3 className="mt-1.5 line-clamp-2 min-h-[2.7rem] sm:min-h-[2.9rem] text-[14.5px] sm:text-[16px] font-bold leading-[1.38] text-[#0E1A2B] group-hover:text-[#D9531E] transition-colors break-keep">
          {product.title}
        </h3>

        {(specCapsules.length > 0 || modelName) && (
          <div className="mt-2 flex flex-wrap items-center gap-1.5">
            {specCapsules.map((tag) => (
              <span
                key={tag}
                className="rounded bg-[#F7F6F3] px-2 py-0.5 text-[11.5px] font-semibold text-[#434B59]"
              >
                {tag}
              </span>
            ))}
            {modelName && specCapsules.length < 2 && (
              <span className="truncate rounded bg-[#F7F6F3] px-2 py-0.5 font-mono text-[11px] font-medium text-[#667085]">
                {modelName}
              </span>
            )}
          </div>
        )}

        <div className="mt-auto pt-3.5">
          <div className="pt-2.5 border-t border-[#E6E3DC] flex items-center justify-between gap-2">
            <div className="min-w-0">
              {sold ? (
                <span className="text-[15px] sm:text-[17px] font-bold text-[#858076]">
                  판매완료
                </span>
              ) : priced ? (
                <span className="text-[16px] xs:text-[17.5px] sm:text-[19px] font-extrabold tracking-tight text-[#0E1A2B] tabular-nums">
                  {priceText}
                </span>
              ) : (
                <span className="inline-flex items-center gap-1 text-[13px] sm:text-[13.5px] font-bold text-[#D9531E]">
                  <Icon d={ICON.phone} className="h-3.5 w-3.5 shrink-0" />
                  <span className="truncate">{priceText}</span>
                </span>
              )}
            </div>

            <span className="inline-flex shrink-0 items-center gap-0.5 text-[12px] font-bold text-[#434B59] group-hover:text-[#D9531E] transition-colors">
              <span className="hidden sm:inline">보기</span>
              <Icon
                d={ICON.right}
                className="h-3.5 w-3.5 transition-transform group-hover:translate-x-0.5"
              />
            </span>
          </div>
        </div>
      </div>
    </article>
  );

  if (onSelect) {
    return (
      <div
        role="button"
        tabIndex={0}
        aria-label={`${product.title} ${isSelectMode ? "선택" : "상세 보기"}`}
        onClick={() => onSelect(product)}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            onSelect(product);
          }
        }}
        className="block h-full w-full cursor-pointer text-left rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#0E1A2B]"
      >
        {cardInner}
      </div>
    );
  }

  return (
    <Link
      href={`/${product.id}`}
      className="block h-full rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#0E1A2B]"
    >
      {cardInner}
    </Link>
  );
}


// 파일 경로: components/products/product-detail-gallery.tsx
"use client";

import React, { useState, useEffect, useCallback } from "react";
import toast from "react-hot-toast";
import { Icon, ICON, SafeImg } from "../../lib/ui";
import { ProductStatusBadge } from "./product-status-badge";
import {
  generatePromoPostText,
  getQuoteBasket,
  isProductSold,
  QUOTE_BASKET_EVENT,
  toggleQuoteBasketItem,
  type QuoteBasketItem,
} from "../../lib/site";

export function ProductDetailGallery({
  id,
  title,
  images,
  status,
  createdAt,
}: {
  id?: string;
  title: string;
  images: string[];
  status: string | null;
  createdAt?: string | null;
}) {
  const displayImages = images.length > 0 ? images : [""];
  const [activeIndex, setActiveIndex] = useState(0);
  const [zoomOpen, setZoomOpen] = useState(false);
  const sold = isProductSold(status);

  useEffect(() => {
    if (!id) return;
    let cancelled = false;
    (async () => {
      try {
        const viewedStr = sessionStorage.getItem("viewed_products") || "[]";
        const viewedList = JSON.parse(viewedStr) as string[];
        if (viewedList.includes(id)) return;

        const res = await fetch(`/api/products/${id}/view`, { method: "POST" });
        if (!res.ok || cancelled) return;

        const nextStr = sessionStorage.getItem("viewed_products") || "[]";
        const nextList = JSON.parse(nextStr) as string[];
        if (!nextList.includes(id)) {
          nextList.push(id);
          sessionStorage.setItem("viewed_products", JSON.stringify(nextList));
        }
      } catch {
        // ignore
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [id]);

  const moveSlide = useCallback(
    (delta: number) => {
      if (displayImages.length < 2) return;
      setActiveIndex(
        (prev) => (prev + delta + displayImages.length) % displayImages.length
      );
    },
    [displayImages.length]
  );

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape" && zoomOpen) {
        setZoomOpen(false);
        return;
      }
      if (displayImages.length < 2) return;
      if (e.key === "ArrowLeft") moveSlide(-1);
      if (e.key === "ArrowRight") moveSlide(1);
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [displayImages.length, moveSlide, zoomOpen]);

  useEffect(() => {
    if (!zoomOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = prev;
    };
  }, [zoomOpen]);

  return (
    <div className="flex flex-col bg-[#FAF9F7]">
      <div
        onClick={() => displayImages[0] && setZoomOpen(true)}
        className={`relative aspect-[4/3] sm:aspect-square w-full overflow-hidden bg-[#EFECE6] flex items-center justify-center p-3 sm:p-5 select-none ${
          displayImages[0] ? "cursor-zoom-in group" : ""
        }`}
        title={displayImages[0] ? "클릭하여 전체화면으로 확대" : undefined}
      >
        <SafeImg
          key={displayImages[activeIndex]}
          src={displayImages[activeIndex]}
          alt={`${title} 사진 ${activeIndex + 1}`}
          eager
          className={`max-h-full max-w-full w-auto h-auto object-contain transition-transform duration-300 group-hover:scale-[1.02] ${
            sold ? "grayscale opacity-75" : ""
          }`}
        />

        {sold && (
          <div className="pointer-events-none absolute inset-0 flex items-center justify-center bg-[#0E1A2B]/45">
            <span className="rounded-sm border border-white/25 bg-[#0E1A2B]/90 px-5 py-2 text-[14px] font-bold tracking-[0.2em] text-white">
              판매완료
            </span>
          </div>
        )}

        <div className="absolute left-4 top-4 z-10">
          <ProductStatusBadge status={status} createdAt={createdAt} />
        </div>

        {displayImages[0] && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              setZoomOpen(true);
            }}
            className="absolute right-3.5 top-3.5 z-10 inline-flex items-center gap-1.5 rounded-full bg-black/65 px-3 py-1.5 text-[11px] font-semibold text-white hover:bg-black/80 transition-colors"
            aria-label="사진 전체화면 확대"
          >
            <Icon d={ICON.search} className="h-3.5 w-3.5" />
            <span>사진 확대</span>
          </button>
        )}

        {displayImages.length > 1 && (
          <>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                moveSlide(-1);
              }}
              aria-label="이전 상품 사진"
              className="absolute left-3 top-1/2 z-10 -translate-y-1/2 grid h-10 w-10 place-items-center rounded-full bg-white/95 text-[#0E1A2B] shadow-md hover:bg-white transition"
            >
              <Icon d={ICON.left} className="h-5 w-5" />
            </button>
            <button
              type="button"
              onClick={(e) => {
                e.stopPropagation();
                moveSlide(1);
              }}
              aria-label="다음 상품 사진"
              className="absolute right-3 top-1/2 z-10 -translate-y-1/2 grid h-10 w-10 place-items-center rounded-full bg-white/95 text-[#0E1A2B] shadow-md hover:bg-white transition"
            >
              <Icon d={ICON.right} className="h-5 w-5" />
            </button>
            <span className="pointer-events-none absolute bottom-3 right-3.5 z-10 rounded-full bg-black/70 px-2.5 py-1 text-[11px] font-bold text-white">
              {activeIndex + 1} / {displayImages.length}
            </span>
          </>
        )}
      </div>

      {displayImages.length > 1 && (
        <div
          className="flex gap-2.5 overflow-x-auto border-t border-[#E4E0D8] bg-white p-3.5"
          role="tablist"
          aria-label="상품 추가 사진 목록"
        >
          {displayImages.map((imgUrl, idx) => (
            <button
              key={imgUrl + idx}
              type="button"
              role="tab"
              aria-selected={activeIndex === idx}
              aria-label={`${idx + 1}번 사진 선택`}
              onClick={() => setActiveIndex(idx)}
              className={`relative h-16 w-16 shrink-0 overflow-hidden rounded border bg-[#F6F5F2] transition-all ${
                activeIndex === idx
                  ? "border-[#D9531E] ring-2 ring-[#D9531E]/35 opacity-100"
                  : "border-[#E4E0D8] opacity-65 hover:opacity-100"
              }`}
            >
              <SafeImg
                src={imgUrl}
                alt={`${title} 썸네일 ${idx + 1}`}
                className="h-full w-full object-cover"
              />
            </button>
          ))}
        </div>
      )}

      {zoomOpen && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label={`${title} 사진 확대 보기`}
          onClick={() => setZoomOpen(false)}
          className="fixed inset-0 z-[90] flex flex-col items-center justify-center bg-black/95 p-3 sm:p-6 select-none"
        >
          <div className="absolute inset-x-4 top-4 z-20 flex items-center justify-between text-white">
            <span className="rounded-full bg-white/15 px-3.5 py-1 text-[13px] font-semibold">
              {activeIndex + 1} / {displayImages.length}
            </span>
            <button
              type="button"
              onClick={() => setZoomOpen(false)}
              aria-label="확대 창 닫기"
              className="grid h-10 w-10 place-items-center rounded-full bg-white/15 text-white hover:bg-white/30 transition"
            >
              <Icon d={ICON.close} className="h-6 w-6" />
            </button>
          </div>

          <div
            onClick={(e) => e.stopPropagation()}
            className="relative flex max-h-[84vh] max-w-full items-center justify-center"
          >
            <SafeImg
              src={displayImages[activeIndex]}
              alt={`${title} 확대 사진 ${activeIndex + 1}`}
              eager
              className="max-h-[82vh] max-w-full w-auto h-auto object-contain rounded"
            />
          </div>

          {displayImages.length > 1 && (
            <>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  moveSlide(-1);
                }}
                aria-label="이전 사진"
                className="absolute left-3 sm:left-6 top-1/2 z-20 -translate-y-1/2 grid h-11 w-11 place-items-center rounded-full bg-white/20 text-white hover:bg-white/35 transition"
              >
                <Icon d={ICON.left} className="h-6 w-6" />
              </button>
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  moveSlide(1);
                }}
                aria-label="다음 사진"
                className="absolute right-3 sm:right-6 top-1/2 z-20 -translate-y-1/2 grid h-11 w-11 place-items-center rounded-full bg-white/20 text-white hover:bg-white/35 transition"
              >
                <Icon d={ICON.right} className="h-6 w-6" />
              </button>
            </>
          )}

          <p className="mt-3 text-[12px] text-white/60">
            화면을 누르거나 ESC 키를 누르면 닫힙니다.
          </p>
        </div>
      )}
    </div>
  );
}

export function CopyProductLinkButton({
  productTitle,
}: {
  productTitle: string;
}) {
  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(window.location.href);
      toast.success("상품 페이지 주소가 복사되었습니다.");
    } catch {
      toast.error("주소 복사에 실패했습니다.");
    }
  };

  return (
    <button
      type="button"
      onClick={handleCopy}
      className="hb-btn-outline h-9 px-3 text-[12.5px]"
      aria-label={`${productTitle} 링크 복사`}
    >
      <span>링크 복사</span>
    </button>
  );
}

/**
 * [신규 기능 ⑥] 당근마켓 · 네이버 카페 · 블로그 홍보글 원클릭 복사 버튼
 */
export function CopyPromoPostButton({
  product,
  className = "",
}: {
  product: {
    id: string;
    title: string;
    category?: string | null;
    price?: number | null;
    status?: string | null;
    condition_grade?: string | null;
    description?: string | null;
  };
  className?: string;
}) {
  const handleCopyPromo = async (e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    try {
      const text = generatePromoPostText(product);
      await navigator.clipboard.writeText(text);
      toast.success("당근마켓·네이버카페·블로그 홍보 원고가 복사되었습니다!");
    } catch {
      toast.error("홍보 원고 복사에 실패했습니다.");
    }
  };

  return (
    <button
      type="button"
      onClick={handleCopyPromo}
      className={
        className ||
        "inline-flex items-center gap-1.5 rounded-md border border-[#DDD9D1] bg-[#FAF9F7] px-3 h-9 text-[12.5px] font-bold text-[#0E1A2B] hover:border-[#0E1A2B] transition-colors"
      }
      title="당근마켓·네이버카페·블로그 업로드용 홍보 문구 복사"
    >
      <Icon d={ICON.copy} className="w-3.5 h-3.5 text-[#D9531E]" />
      <span>당근·카페 홍보글 복사</span>
    </button>
  );
}

/**
 * [신규 기능 ①] 상세 페이지용 관심 매물 견적함 담기 토글 버튼
 */
export function QuoteBasketButton({
  item,
  className = "",
}: {
  item: QuoteBasketItem;
  className?: string;
}) {
  const [inBasket, setInBasket] = useState(false);

  useEffect(() => {
    const sync = () => {
      setInBasket(getQuoteBasket().some((x) => x.id === item.id));
    };
    sync();
    window.addEventListener(QUOTE_BASKET_EVENT, sync);
    window.addEventListener("storage", sync);
    return () => {
      window.removeEventListener(QUOTE_BASKET_EVENT, sync);
      window.removeEventListener("storage", sync);
    };
  }, [item.id]);

  const handleToggle = () => {
    const res = toggleQuoteBasketItem(item);
    if (res.limitReached) {
      toast.error("견적함에는 최대 8개까지 담을 수 있습니다.");
    } else if (res.added) {
      toast.success("관심 매물 견적함에 담았습니다.");
    } else {
      toast("견적함에서 제외했습니다.");
    }
  };

  return (
    <button
      type="button"
      onClick={handleToggle}
      aria-pressed={inBasket}
      className={
        className ||
        `inline-flex h-11 w-full items-center justify-center gap-1.5 rounded-md border text-[13.5px] font-bold transition-colors ${
          inBasket
            ? "border-[#D9531E] bg-[#FFF5F0] text-[#D9531E]"
            : "border-[#DDD9D1] bg-[#FAF9F7] text-[#0E1A2B] hover:border-[#0E1A2B]"
        }`
      }
    >
      <Icon
        d={inBasket ? ICON.check : ICON.plus}
        className="w-4 h-4 text-[#D9531E]"
      />
      <span>
        {inBasket
          ? "견적함에 담김 (우측 하단에서 묶음 문의 가능)"
          : "관심 매물 견적함에 담기 (복수 품목 묶음 문의)"}
      </span>
    </button>
  );
}


import React from "react";
import {
  getProductStatusLabel,
  isProductReserved,
  isProductSold,
  isRecentlyCreated,
} from "../../lib/site";

export function ProductStatusBadge({
  status,
  createdAt,
  showNew = true,
  className = "",
}: {
  status?: string | null;
  createdAt?: string | null;
  showNew?: boolean;
  className?: string;
}) {
  const sold = isProductSold(status);
  const reserved = isProductReserved(status);
  const label = getProductStatusLabel(status);

  const isFresh = showNew && !sold && isRecentlyCreated(createdAt, 7);

  return (
    <div className={`inline-flex flex-wrap items-center gap-1.5 ${className}`}>
      <span
        className={`inline-block rounded-sm px-2.5 py-1 text-[11px] font-bold tracking-wide text-white shadow-2xs ${
          sold
            ? "bg-[#6B7280]"
            : reserved
            ? "bg-[#B45309]"
            : "bg-[#0E1A2B]"
        }`}
      >
        {label}
      </span>
      {isFresh && (
        <span className="inline-block rounded-sm bg-[#D9531E] px-2 py-1 text-[11px] font-bold tracking-wide text-white shadow-2xs">
          NEW
        </span>
      )}
    </div>
  );
}


// 파일 경로: components/ui/interactive-effects.tsx
"use client";

import React from "react";
import { STORE, telHref, smsHref } from "../../lib/site";

/**
 * 1. Clean Surface Card Wrapper (기존 SpotlightCard 호환 래퍼 — 과장된 광원 효과 제거)
 */
export function SpotlightCard({
  children,
  className = "",
  as: Component = "div",
}: {
  children: React.ReactNode;
  className?: string;
  spotlightColor?: string;
  as?: "div" | "li" | "article";
}) {
  return (
