// 파일 경로: scripts/test-phase4-scenarios.mjs
// 실행 방법: node scripts/test-phase4-scenarios.mjs

const BASE_URL = process.env.TEST_BASE_URL || "http://localhost:3000";

async function runPhase4RegressionTests() {
  console.log("=========================================================");
  console.log("🧪 한밭중고전자 Phase 4 10대 시나리오 회귀 검증 시작");
  console.log("=========================================================\n");

  let passed = 0;
  let total = 0;

  function check(name, cond, detail = "") {
    total++;
    if (cond) {
      passed++;
      console.log(`✅ [PASS] ${name}`);
    } else {
      console.error(`❌ [FAIL] ${name} ${detail ? `(${detail})` : ""}`);
    }
  }

  // 로컬 서버 실행 여부 먼저 확인
  let serverOnline = false;
  try {
    const ping = await fetch(`${BASE_URL}/api/inquiries?limit=1`);
    serverOnline = ping.status > 0;
  } catch {
    serverOnline = false;
  }

  if (!serverOnline) {
    console.error(
      `❌ 로컬 개발 서버(${BASE_URL})가 켜져 있지 않아 HTTP 시나리오 테스트를 실행할 수 없습니다. 'npm run dev' 실행 후 다시 테스트하세요.`
    );
    process.exit(1);
  }

  // 시나리오 1: 매입 신청 실패 검증 (필수 항목 누락 또는 잘못된 전화번호/비밀번호)
  {
    const res = await fetch(`${BASE_URL}/api/inquiries`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: "홍길동",
        phone: "1234", // 잘못된 전화번호
        password: "12", // 4자리 미만
        inquiry_type: "내 물건 팔기",
        category: "[냉장고] 삼성 냉장고 매입 신청",
      }),
    });
    check(
      "1. 매입 신청 실패 시나리오 (유효하지 않은 연락처/비밀번호 400 거부)",
      res.status === 400
    );
  }

  // 시나리오 2: 무인증 공지사항 등록 차단 (운영 DB 오염 없이 POST 권한 검증)
  {
    const res = await fetch(`${BASE_URL}/api/inquiries`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        is_notice: true,
        category: "무인증 공지 등록 시도",
        description: "차단되어야 합니다.",
      }),
    });
    check(
      "2. 무인증 공지사항 등록 차단 (401 또는 403 반환, 운영 DB 오염 방지)",
      res.status === 401 || res.status === 403
    );
  }

  // 시나리오 3 & 4: 권한 없는 사용자의 관리자 답변 등록 및 상태 변경 차단
  {
    const res = await fetch(`${BASE_URL}/api/inquiries/00000000-0000-0000-0000-000000000000`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        status: "답변완료",
        admin_reply: "무권한 답변 시도",
      }),
    });
    check(
      "3 & 4. 권한 없는 관리자 답변/상태 변경 요청 차단 (403 또는 404 반환)",
      res.status === 403 || res.status === 404
    );
  }

  // 시나리오 5 & 6: Gemini 상품 분석 API 무인증 차단 및 파일 업로드 제한
  {
    const unauthRes = await fetch(`${BASE_URL}/api/analyze-product`, {
      method: "POST",
    });
    check(
      "5 & 6. 무인증 Gemini 상품 분석 호출 차단 (401 Unauthorized)",
      unauthRes.status === 401
    );
  }

  // 시나리오 7 & 8: 알림 설정 누락(Alimtalk) 및 텔레그램 무인증 수동 재발송(forceRetry) 차단 검증
  {
    const alimRes = await fetch(`${BASE_URL}/api/alimtalk`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: "테스트", phone: "010-0000-0000" }),
    });
    const alimBody = await alimRes.json().catch(() => ({}));
    check(
      "7. 알림톡 설정 누락 시 거짓 성공(success: true) 대신 NOT_CONFIGURED(501) 반환",
      alimRes.status === 501 &&
        alimBody.success === false &&
        alimBody.status === "NOT_CONFIGURED"
    );

    const tgForceRes = await fetch(`${BASE_URL}/api/telegram`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: "테스트고객",
        phone: "010-1234-5678",
        type: "내 물건 팔기",
        title: "매입 테스트",
        forceRetry: true,
      }),
    });
    check(
      "8. 텔레그램 무인증 수동 재발송(forceRetry: true) 차단 (401 Unauthorized, 실제 알림 오발송 방지)",
      tgForceRes.status === 401
    );
  }

  // 시나리오 9: 잘못된 API 요청 본문 처리
  {
    const badRes = await fetch(`${BASE_URL}/api/telegram`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: "invalid-json-payload",
    });
    check("9. 잘못된 JSON API 요청 시 400 Bad Request 처리", badRes.status === 400);
  }

  console.log(`\n=========================================================`);
  console.log(`최종 결과: ${passed} / ${total} 시나리오 검증 통과`);
  console.log(`=========================================================`);

  if (passed < total) {
    process.exit(1);
  }
}

runPhase4RegressionTests();


// 파일 경로: scripts/verify-predeploy.mjs
// 실행 방법: node scripts/verify-predeploy.mjs

import fs from "fs";
import path from "path";

const ROOT = process.cwd();

function fileExists(relPath) {
  return fs.existsSync(path.join(ROOT, relPath));
}

function readFileSafe(relPath) {
  const full = path.join(ROOT, relPath);
  if (!fs.existsSync(full)) return "";
  return fs.readFileSync(full, "utf8");
}

function runPredeployChecks() {
  console.log("=========================================================");
  console.log("🚀 한밭중고전자 배포 전 최종 정적·보안·SEO 무결성 검증");
  console.log("=========================================================\n");

  let passed = 0;
  let total = 0;

  function check(title, ok, hint = "") {
    total++;
    if (ok) {
      passed++;
      console.log(`✅ [PASS] ${title}`);
    } else {
      console.error(`❌ [FAIL] ${title}${hint ? ` -> \${hint}` : ""}`);
    }
  }

  check(
    "1. 잘못된 경로의 app/api/[id] 폴더가 존재하지 않음",
    !fileExists("app/api/[id]/route.ts"),
    "app/api/[id] 폴더를 삭제하고 app/api/inquiries/[id]/route.ts만 남겨두세요."
  );

  const inqDetailRoute = readFileSafe("app/api/inquiries/[id]/route.ts");
  check(
    "2. 문의 단건 API(app/api/inquiries/[id]/route.ts)에 POST/PATCH/DELETE 핸들러 정상 존재",
    fileExists("app/api/inquiries/[id]/route.ts") &&
      inqDetailRoute.includes("export async function POST") &&
      inqDetailRoute.includes("export async function PATCH") &&
      inqDetailRoute.includes("export async function DELETE"),
    "app/api/inquiries/[id]/route.ts에 목록 코드가 잘못 덮어써지지 않았는지 확인하세요."
  );

  const twConfig = readFileSafe("tailwind.config.js");
  check(
    "3. tailwind.config.js에 ./lib/** 및 ./components/** 스캔 경로 포함",
    twConfig.includes("./lib/") && twConfig.includes("./components/")
  );

  const analyzeProd = readFileSafe("app/api/analyze-product/route.ts");
  const analyzeDeliv = readFileSafe("app/api/analyze-delivery/route.ts");
  check(
    "4. Gemini 상품/배송 분석 API에 gemini-3.8-flash 유지, gemini-2.5-flash 폴백 및 관리자 검증 포함",
    analyzeProd.includes("gemini-3.8-flash") &&
      analyzeProd.includes("gemini-2.5-flash") &&
      analyzeProd.includes("verifyAdminRequest") &&
      analyzeDeliv.includes("gemini-3.8-flash") &&
      analyzeDeliv.includes("gemini-2.5-flash") &&
      !analyzeDeliv.includes("gemini-3.5-flash") &&
      analyzeDeliv.includes("verifyAdminRequest"),
    "analyze-delivery의 폴백 모델명이 gemini-2.5-flash인지 확인하세요."
  );

  check(
    "5. 서브 페이지(/gallery, /inquiry, /purchase, /admin) 레이아웃 메타데이터 분리",
    fileExists("app/gallery/layout.tsx") &&
      fileExists("app/inquiry/layout.tsx") &&
      fileExists("app/purchase/layout.tsx") &&
      fileExists("app/admin/layout.tsx")
  );

  check(
    "6. 404(app/not-found.tsx) 및 오류 복구(app/error.tsx) 페이지 존재 확인",
    fileExists("app/not-found.tsx") && fileExists("app/error.tsx")
  );

  const prodDetailPage = readFileSafe("app/[id]/page.tsx");
  const prodCardComp = readFileSafe("components/products/product-card.tsx");
  check(
    "7. 상품 상세 페이지(app/[id]/page.tsx) 및 상품 카드(components/products/product-card.tsx) 컴포넌트 무결성 확인",
    prodDetailPage.includes("export default async function ProductDetailPage") &&
      prodDetailPage.includes("export async function generateMetadata") &&
      prodCardComp.includes("export function ProductCard"),
    "상품 상세 페이지 또는 ProductCard 컴포넌트가 다른 코드로 덮어써지지 않았는지 확인하세요."
  );

  console.log("\n=========================================================");
  console.log(`검증 완료: ${passed} / ${total} 항목 통과`);
  console.log("=========================================================");

  if (passed < total) {
    process.exit(1);
  }
}

runPredeployChecks();


